content:
I'll create a Terraform module focused on the three required resources (S3 + RDS + IAM), with clean variable/output interfaces and dev/prod separation via tfvars.

## Directory Layout

```
.
├── modules/
│   └── app_data/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       └── versions.tf
├── envs/
│   ├── dev/
│   │   ├── main.tf
│   │   ├── backend.tf
│   │   └── dev.tfvars
│   └── prod/
│       ├── main.tf
│       ├── backend.tf
│       └── prod.tfvars
└── README.md
```

---

## Module: `modules/app_data`

### `modules/app_data/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}
```

### `modules/app_data/variables.tf`

```hcl
variable "environment" {
  description = "Environment name (dev|prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be dev or prod."
  }
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

# ---------- S3 ----------
variable "bucket_name" {
  description = "Globally-unique S3 bucket name for application assets"
  type        = string
}

variable "enable_replication" {
  description = "Enable cross-region replication (prod)"
  type        = bool
  default     = false
}

variable "replication_region" {
  description = "Destination region for CRR"
  type        = string
  default     = "us-west-2"
}

# ---------- RDS ----------
variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_multi_az" {
  description = "Enable Multi-AZ deployment"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Encrypt RDS storage"
  type        = bool
  default     = true
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username"
  type        = string
  default     = "appadmin"
}

variable "db_password" {
  description = "Master password (pass via -var-file / SOPS, never commit plaintext)"
  type        = string
  sensitive   = true
}

variable "db_backup_retention" {
  description = "Backup retention in days (>=7 per policy)"
  type        = number
  default     = 7
  validation {
    condition     = var.db_backup_retention >= 7
    error_message = "backup retention must be >= 7 days."
  }
}

variable "db_subnet_ids" {
  description = "Subnet IDs for the DB subnet group"
  type        = list(string)
}

variable "db_security_group_ids" {
  description = "Security group IDs attached to RDS"
  type        = list(string)
}

# ---------- IAM ----------
variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN for IRSA trust (prod least-privilege)"
  type        = string
  default     = ""
}

variable "oidc_provider_url" {
  description = "EKS OIDC provider URL (without https://)"
  type        = string
  default     = ""
}

variable "service_account_namespace" {
  description = "K8s namespace of the service account"
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "K8s service account name"
  type        = string
  default     = "app-sa"
}
```

### `modules/app_data/main.tf`

```hcl
locals {
  is_prod = var.environment == "prod"

  base_tags = merge(var.tags, {
    Environment = var.environment
    ManagedBy   = "terraform"
    Module      = "app_data"
  })
}

########################################
# S3 BUCKET (assets)
########################################

resource "aws_s3_bucket" "assets" {
  bucket = var.bucket_name
  tags   = local.base_tags
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ----- Cross-region replication (prod only) -----

resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = "${var.bucket_name}-replica"
  tags     = local.base_tags
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica
  bucket   = aws_s3_bucket.replica[0].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "replication_assume" {
  count = var.enable_replication ? 1 : 0
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count              = var.enable_replication ? 1 : 0
  name               = "${var.name_prefix}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume[0].json
  tags               = local.base_tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_replication ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }
}

resource "aws_iam_role_policy" "replication" {
  count  = var.enable_replication ? 1 : 0
  name   = "${var.name_prefix}-s3-replication"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count      = var.enable_replication ? 1 : 0
  depends_on = [aws_s3_bucket_versioning.assets]
  role       = aws_iam_role.replication[0].arn
  bucket     = aws_s3_bucket.assets.id

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }
}

########################################
# RDS POSTGRESQL
########################################

resource "aws_db_subnet_group" "this" {
  name       = "${var.name_prefix}-db-subnets"
  subnet_ids = var.db_subnet_ids
  tags       = local.base_tags
}

resource "aws_db_instance" "postgres" {
  identifier     = "${var.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "16"
  instance_class = var.db_instance_class

  allocated_storage = var.db_allocated_storage
  storage_encrypted = var.db_storage_encrypted
  storage_type      = "gp3"

  db_name  = var.db_name
  username = var.db_username
  password = var.db_password

  multi_az            = var.db_multi_az
  publicly_accessible = false

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = var.db_security_group_ids

  backup_retention_period = var.db_backup_retention
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.name_prefix}-postgres-final"

  apply_immediately = false
  tags              = local.base_tags
}

########################################
# IAM ROLE FOR SERVICE ACCOUNT
########################################

# Assume-role trust: OIDC/IRSA for prod (least priv), account principal fallback for dev
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "sa_assume" {
  dynamic "statement" {
    for_each = var.oidc_provider_arn != "" ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRoleWithWebIdentity"]
      principals {
        type        = "Federated"
        identifiers = [var.oidc_provider_arn]
      }
      condition {
        test     = "StringEquals"
        variable = "${var.oidc_provider_url}:sub"
        values   = ["system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"]
      }
      condition {
        test     = "StringEquals"
        variable = "${var.oidc_provider_url}:aud"
        values   = ["sts.amazonaws.com"]
      }
    }
  }

  # Dev fallback: allow same-account roles to assume (programmatic access via role)
  dynamic "statement" {
    for_each = var.oidc_provider_arn == "" ? [1] : []
    content {
      effect  = "Allow"
      actions = ["sts:AssumeRole"]
      principals {
        type        = "AWS"
        identifiers = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${var.name_prefix}-app-sa"
  assume_role_policy = data.aws_iam_policy_document.sa_assume.json
  tags               = local.base_tags
}

# Least-privilege policy: scoped to this bucket + no wildcard actions
data "aws_iam_policy_document" "sa_policy" {
  statement {
    sid    = "ListAppBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid    = "ReadWriteAppObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }
}

resource "aws_iam_role_policy" "service_account" {
  name   = "${var.name_prefix}-app-sa-policy"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.sa_policy.json
}
```

### `modules/app_data/outputs.tf`

```hcl
output "bucket_name" {
  description = "Name of the assets S3 bucket"
  value       = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "replica_bucket_arn" {
  description = "ARN of the replica bucket (null if disabled)"
  value       = var.enable_replication ? aws_s3_bucket.replica[0].arn : null
}

output "db_endpoint" {
  description = "RDS connection endpoint"
  value       = aws_db_instance.postgres.endpoint
}

output "db_name" {
  value = aws_db_instance.postgres.db_name
}

output "db_connection_string" {
  description = "Postgres connection string (sensitive)"
  value       = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.postgres.endpoint}/${aws_db_instance.postgres.db_name}"
  sensitive   = true
}

output "service_account_role_arn" {
  description = "IAM role ARN for the service account (IRSA annotation)"
  value       = aws_iam_role.service_account.arn
}
```

---

## Environments

### `envs/dev/backend.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  backend "s3" {
    bucket = "my-org-tfstate"
    key    = "app-data/dev/terraform.tfstate"
    region = "us-east-1"
    # DynamoDB lock table recommended
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

### `envs/dev/main.tf`

```hcl
provider "aws" {
  region = var.region
}

# Replica provider (unused in dev but required by module alias)
provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

variable "region" { type = string }
variable "db_password" {
  type      = string
  sensitive = true
}
variable "db_subnet_ids"        { type = list(string) }
variable "db_security_group_ids" { type = list(string) }

module "app_data" {
  source = "../../modules/app_data"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment = "dev"
  name_prefix = "myapp-dev"
  bucket_name = "myapp-dev-assets-1234"

  # S3
  enable_replication = false

  # RDS - small, single AZ
  db_instance_class     = "db.t3.micro"
  db_multi_az           = false
  db_storage_encrypted  = true
  db_backup_retention   = 7
  db_password           = var.db_password
  db_subnet_ids         = var.db_subnet_ids
  db_security_group_ids = var.db_security_group_ids

  # IAM - dev uses account principal fallback (no OIDC set)
  service_account_namespace = "default"
  service_account_name      = "app-sa"

  tags = { Team = "platform" }
}

output "db_endpoint"    { value = module.app_data.db_endpoint }
output "sa_role_arn"    { value = module.app_data.service_account_role_arn }
output "bucket_name"    { value = module.app_data.bucket_name }
```

### `envs/dev/dev.tfvars`

```hcl
region                = "us-east-1"
db_subnet_ids         = ["subnet-aaa", "subnet-bbb"]
db_security_group_ids = ["sg-devrds"]
# db_password NOT here — supplied via SOPS-decrypted file or TF_VAR_db_password
```

### `envs/prod/main.tf`

```hcl
provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

variable "region"            { type = string }
variable "db_password"       { type = string, sensitive = true }
variable "db_subnet_ids"     { type = list(string) }
variable "db_security_group_ids" { type = list(string) }
variable "oidc_provider_arn" { type = string }
variable "oidc_provider_url" { type = string }

module "app_data" {
  source = "../../modules/app_data"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  environment = "prod"
  name_prefix = "myapp-prod"
  bucket_name = "myapp-prod-assets-1234"

  # S3 - with cross-region replication
  enable_replication = true
  replication_region = "us-west-2"

  # RDS - larger, multi-AZ, encrypted
  db_instance_class     = "db.t3.medium"
  db_multi_az           = true
  db_storage_encrypted  = true
  db_allocated_storage  = 100
  db_backup_retention   = 14
  db_password           = var.db_password
  db_subnet_ids         = var.db_subnet_ids
  db_security_group_ids = var.db_security_group_ids

  # IAM - least-privilege via OIDC/IRSA
  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  service_account_namespace = "app"
  service_account_name      = "app-sa"

  tags = { Team = "platform" }
}

output "db_endpoint" { value = module.app_data.db_endpoint }
output "sa_role_arn" { value = module.app_data.service_account_role_arn }
output "bucket_name" { value = module.app_data.bucket_name }
```

### `envs/prod/backend.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  backend "s3" {
    bucket         = "my-org-tfstate"
    key            = "app-data/prod/terraform.tfstate"   # separate key => isolated state
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}
```

### `envs/prod/prod.tfvars`

```hcl
region                = "us-east-1"
db_subnet_ids         = ["subnet-ppp", "subnet-qqq", "subnet-rrr"]
db_security_group_ids = ["sg-prodrds"]
oidc_provider_arn     = "arn:aws:iam::111122223333:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
oidc_provider_url     = "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
# db_password via SOPS / TF_VAR_db_password
```

---

## Secret handling (never plaintext in Git)

Two idiomatic options; pick one:

**Option A — SOPS-encrypted tfvars**
```bash
# secrets.enc.yaml is committed encrypted; decrypt at apply time
sops -d envs/prod/secrets.enc.json > /tmp/secrets.json
terraform apply -var-file=prod.tfvars -var="db_password=$(jq -r .db_password /tmp/secrets.json)"
```

**Option B — Environment variable**
```bash
export TF_VAR_db_password="$(sops -d --extract '["db_password"]' secrets.enc.yaml)"
terraform apply -var-file=prod.tfvars
```

`db_password` is marked `sensitive` and never written to a committed `.tfvars`.

---

## Usage

```bash
# Dev
cd envs/dev
terraform init
terraform apply -var-file=dev.tfvars

# Prod (independent state key => changing prod cannot touch dev)
cd ../prod
terraform init
terraform apply -var-file=prod.tfvars
```

---

## How this meets the acceptance criteria

| Criterion | Implementation |
|---|---|
| **Bucket** | `aws_s3_bucket_versioning` = Enabled, `AES256` SSE, full `public_access_block` |
| **RDS** | `deletion_protection = true`, `backup_retention >= 7` (validated), `publicly_accessible = false`, `storage_encrypted` |
| **Secret** | `db_password` is `sensitive`, injected via SOPS/`TF_VAR_`, never in committed tfvars |
| **IAM least-priv** | Bucket-scoped actions only, no `s3:*` wildcards; prod trust via OIDC subject condition |
| **HTTPS / Cluster** | Out of scope for this bucket+RDS+IAM module (would live in sibling `eks`/`cdn` modules) |
| **Env isolation** | Separate backend state keys per env + per-env tfvars; prod apply never mutates dev state |

**Note:** The task scope names S3 + RDS + IAM. The canonical spine also lists EKS and CloudFront/ACM — those belong in sibling modules (`modules/eks`, `modules/cdn`) composed the same way in each `envs/*/main.tf`. I kept this module tightly scoped to the three requested resources; let me know if you want the EKS + CloudFront modules fleshed out too.
